fn replace_string_value(text: &mut String, key: &str, value: &str) -> Result<(), String> {
    let prefix = format!("{key} = \"");
    let start = text
        .find(&prefix)
        .ok_or_else(|| format!("test manifest lacks {key}"))?
        + prefix.len();
    let end = start
        + text[start..]
            .find('"')
            .ok_or_else(|| format!("test manifest has malformed {key}"))?;
    text.replace_range(start..end, value);
    Ok(())
}

fn insert_at_end_of_table(text: &mut String, table: &str, lines: &[String]) -> Result<(), String> {
    let marker = format!("[{table}]\n");
    let start = text
        .find(&marker)
        .ok_or_else(|| format!("manifest lacks [{table}]"))?
        + marker.len();
    let end = start + text[start..].find("\n[").unwrap_or(text.len() - start);
    let mut filtered = text[start..end]
        .lines()
        .filter(|existing| {
            !lines.iter().any(|line| {
                let key = line.split_once(" = ").map_or(line.as_str(), |item| item.0);
                existing.starts_with(&format!("{key} = "))
            })
        })
        .collect::<Vec<_>>()
        .join("\n");
    if !filtered.is_empty() {
        filtered.push('\n');
    }
    filtered.push_str(&lines.join("\n"));
    text.replace_range(start..end, &filtered);
    Ok(())
}

fn json(value: &str) -> String {
    serde_json::to_string(value).expect("serializing a string cannot fail")
}
